def seed_if_needed(db_path: str) -> None:
    """Если файла БД ещё нет (пустой Volume/первый деплой) — создаёт его из сохранённого
    снимка с реальными данными. Если файл уже существует (бот уже работал и что-то
    записал) — ничего не трогает, чтобы не затереть более свежие данные."""
    if os.path.exists(db_path) and os.path.getsize(db_path) > 0:
        return
    directory = os.path.dirname(db_path)
    if directory:
        os.makedirs(directory, exist_ok=True)
    with open(db_path, "wb") as f:
        f.write(base64.b64decode(_SEED_DB_B64))
    print(f"[seed_db] Восстановил {db_path} из сохранённого снимка БД.")
